<script lang="ts">
 let {session,hydratedReady,busy,pendingJob,anchorNotes,anchorEdits,manifestoNote,matrixNote,reviewAnswers,onAction}:{session:any;hydratedReady:boolean;busy:boolean;pendingJob:string|null;anchorNotes:Record<string,string>;anchorEdits:Record<string,string>;manifestoNote:string;matrixNote:string;reviewAnswers:Record<string,'pass'|'fail'>;onAction:(action:string,extra?:Record<string,unknown>)=>Promise<boolean>}=$props();
 let outputs=$derived(session.outputs);
 let priorSessionId='',priorSentences=new Map<string,string>();
 $effect(()=>{if(!outputs)return;const changedSession=session.sessionId!==priorSessionId;for(const anchor of outputs.outputs.anchors){if(changedSession||!priorSentences.has(anchor.key)||priorSentences.get(anchor.key)!==anchor.sentence)anchorEdits[anchor.key]=anchor.sentence;}priorSessionId=session.sessionId;priorSentences=new Map(outputs.outputs.anchors.map((anchor:{key:string;sentence:string})=>[anchor.key,anchor.sentence]));});
 const disabled=$derived(!hydratedReady||busy||!!pendingJob);
</script>
<section class="space-y-5 rounded border p-4"><h2 class="text-xl">Conviction outputs</h2><p>Review each output independently. Approving one does not approve the others.</p>
 <section class="space-y-3"><h3 class="text-lg font-medium">Seven conviction anchors</h3>{#each outputs.outputs.anchors as anchor}<article class="space-y-2 rounded border p-3"><h4 class="font-medium">{anchor.key.replaceAll('-',' ')}</h4><p>Approval status: <strong>{outputs.anchorStatus?.[anchor.key]??'candidate'}</strong></p><label class="block">Candidate sentence<textarea class="block w-full" rows="3" bind:value={anchorEdits[anchor.key]} disabled={disabled}></textarea></label><div class="flex flex-wrap gap-2"><button disabled={disabled||!anchorEdits[anchor.key]?.trim()} onclick={()=>onAction('edit-anchor',{anchorKey:anchor.key,sentence:anchorEdits[anchor.key]})}>Save edited sentence</button><button disabled={disabled||outputs.anchorStatus?.[anchor.key]==='locked'} onclick={()=>onAction('confirm',{part:'anchor',anchorKey:anchor.key})}>Approve this anchor</button></div><label class="block">Revision request<textarea class="block w-full" rows="2" bind:value={anchorNotes[anchor.key]} disabled={disabled}></textarea></label><button disabled={disabled||!anchorNotes[anchor.key]?.trim()} onclick={()=>onAction('revise-anchor',{anchorKey:anchor.key,note:anchorNotes[anchor.key]})}>Request a revised candidate</button></article>{/each}</section>
 <section class="space-y-2 rounded border p-3"><h3 class="text-lg font-medium">Manifesto</h3><p>Approval status: <strong>{outputs.status.manifesto}</strong></p><p>{outputs.outputs.manifesto}</p><label>Revision request<textarea class="block w-full" bind:value={manifestoNote} disabled={disabled}></textarea></label><button disabled={disabled||!manifestoNote.trim()} onclick={()=>onAction('revise-manifesto',{note:manifestoNote})}>Request revised manifesto</button><button disabled={disabled||outputs.status.manifesto==='locked'} onclick={()=>onAction('confirm',{part:'manifesto'})}>Approve manifesto</button></section>
 <section class="space-y-2 rounded border p-3"><h3 class="text-lg font-medium">Language bank</h3><p>Approval status: <strong>{outputs.status.languageBank}</strong></p>{#each outputs.outputs.languageBank as group}<p><strong>{group.category}:</strong> {group.phrases.join(' · ')}</p>{/each}<button disabled={disabled||outputs.status.languageBank==='locked'} onclick={()=>onAction('confirm',{part:'languageBank'})}>Approve language bank</button></section>
 <section class="space-y-2 rounded border p-3"><h3 class="text-lg font-medium">Evidence matrix and claims boundary</h3><p>Approval status: <strong>{outputs.status.evidenceMatrix}</strong></p>{#each outputs.outputs.evidenceMatrix as row}<p><strong>{row.zone}: {row.claim}</strong> — {row.evidence.map((e:{item:string;category:string})=>e.item).join('; ')}</p>{/each}<h4>Can claim</h4><ul>{#each outputs.outputs.claimsBoundaryInputs.canClaim as x}<li>{x}</li>{/each}</ul><h4>Must qualify</h4><ul>{#each outputs.outputs.claimsBoundaryInputs.mustQualify as x}<li>{x}</li>{/each}</ul><h4>Cannot claim</h4><ul>{#each outputs.outputs.claimsBoundaryInputs.cannotClaim as x}<li>{x}</li>{/each}</ul><label>Revision request<textarea class="block w-full" bind:value={matrixNote} disabled={disabled}></textarea></label><button disabled={disabled||!matrixNote.trim()} onclick={()=>onAction('revise-matrix',{note:matrixNote})}>Request revised evidence matrix</button><button disabled={disabled||outputs.status.evidenceMatrix==='locked'} onclick={()=>onAction('confirm',{part:'evidenceMatrix'})}>Approve evidence matrix</button></section>
 <section class="space-y-2 rounded border p-3"><h3 class="text-lg font-medium">Facts anchor</h3><p>Approval status: <strong>{outputs.factsAnchor.status}</strong></p>{#each outputs.factsAnchor.items as fact}<p><strong>{fact.fact}:</strong> {fact.detail}</p>{/each}<button disabled={disabled||outputs.factsAnchor.status==='locked'} onclick={()=>onAction('confirm',{part:'factsAnchor'})}>Approve facts anchor</button></section>
 <section class="space-y-2 rounded border p-3"><h3 class="text-lg font-medium">Public record readiness</h3><p>{outputs.publicRecordReadiness.state}: {outputs.publicRecordReadiness.sentence}</p><p>This is a separate assessment. Confirming it is optional for sealing; quality review and named-source attribution govern sealing.</p><p>Assessment status: <strong>{outputs.readinessConfirmed?'confirmed':'not confirmed'}</strong></p><button disabled={disabled||outputs.readinessConfirmed} onclick={()=>onAction('confirm',{part:'readiness'})}>Confirm readiness assessment</button></section>
</section>
